function UIDisasterResponsePanel:GetRankNum(type)
    return #self._allRankMap[checkInt(type or self:GetSelectedType())]
end

function UIDisasterResponsePanel:SetSelectedType(type, rank, NoNeedAnim)
    local oldType = self:GetSelectedType()
    self._selectedType = checkInt(type)
    if self:GetSelectedType() == oldType or self:GetSelectedType() <= 0 then
        return
    end

    local maxRank = self:GetRankNum(self:GetSelectedType())
    self:SetSelectedRank(rank or math.min(self:GetProgressByType() + 1, maxRank), true, true)

    -- refresh view
    local rankNum = self:GetRankNum()
    if not self.RankListView.IsListViewInit then
        self.RankListView:InitListView(rankNum, Bind(self, self.OnGetRankItemByIndex), { mTargetIndex = self:GetSelectedRank() - 1 })
    else
        GameUtils.ReloadData(self.RankListView, rankNum)
        self.RankListView:MovePanelToItemIndex(self:GetSelectedRank() - 1)
    end

    -- update anim
    self:PlayChapterCellAnim(self:GetSelectedType(), true)
    self:PlayChapterCellAnim(oldType, false)

    if not NoNeedAnim then
        CfUtils.PlayAnimator(self.Container, "Change")
    end

    for index = 1, 3 do
        local icon = self['ImgRole' .. index]
        local goodsId = checkInt(self:GetChapterDataByIndex(self:GetSelectedType()).suitId[index])
        local hasReward = goodsId > 0
        KTool.SetActive(icon, hasReward)
        if hasReward then
            CfUtils.FillImage(icon, string.format("Arts/Role/equip/Small/tarot_part_img_%s.png", goodsId))
        end
    end
end
function UIDisasterResponsePanel:GetSelectedType()
    return checkInt(self._selectedType)
end

---SetSelectedRank
---@param rank table
---@param isNew boolean
---@param isUnlocked boolean
function UIDisasterResponsePanel:SetSelectedRank(rank, isNew, isUnlocked)
    isUnlocked = checkBool(isUnlocked)
    local oldRank = self:GetSelectedRank()
    self._selectedRank = checkInt(rank)
    if not isNew and oldRank == self:GetSelectedRank() then
        return
    end

    local questVo = self:GetQuestDataByIndex()
    KTool.SetActive(self.BtnThree.transform.parent.gameObject, isUnlocked)
    if  isUnlocked then
        --- If is not unlocked then the go fight button hidden
        -- refresh three mode
        if self:IsThreeMode() then
            self:SetThreeModeStatus(equipQuestComp:IsPassQuestById(self:GetQuestIdByIndex()))
        else
            self:SetThreeModeStatus(false)
        end
    end

    -- refresh rewards
    if isNull(self.CommonGoodsList.Env) then
        self.CommonGoodsList:Init()
    end
    local rewardList = {}
    local questRewardVo = RewardConfMgr:GetInstance():GetQuestRewardVo(questVo.id)
    for _, goodsId in pairs(string.split(questRewardVo.showReward, ";")) do
        table.insert(rewardList, { goodsId = goodsId })
    end
    self.CommonGoodsList.Env:FreshBaseUI(rewardList, false, false, false)

    -- update tab
    self.RankListView:RefreshItemByItemIndex(oldRank - 1)
    self.RankListView:RefreshItemByItemIndex(self:GetSelectedRank() - 1)
end
function UIDisasterResponsePanel:GetSelectedRank()
    return checkInt(self._selectedRank)
end

---@return QuestSeniorEquipTypeVo
function UIDisasterResponsePanel:GetChapterDataByIndex(index)
    return self._questTypeSetting:Get(index)
end

---@return QuestSeniorEquipChapterVo
function UIDisasterResponsePanel:GetQuestDataByIndex(index)
    return self:GetQuestDataByQuestId(self:GetQuestIdByIndex(index))
end

---@return QuestSeniorEquipChapterVo
function UIDisasterResponsePanel:GetQuestDataByQuestId(questId)
    return QuestConfMgr:GetInstance():GetQuestVoById(questId)
end

function UIDisasterResponsePanel:GetQuestIdByIndex(index)
    local typeQuestDt = checkTable(self._allRankMap[self:GetSelectedType()])
    return checkInt(typeQuestDt[index or self:GetSelectedRank()])
end

function UIDisasterResponsePanel:SetThreeModeStatus(status)
    self._isThree = checkBool(status)
    KTool.SetActive(self.ImgThree, self:IsThreeMode())
    KTool.SetActive(self.ImgSelect, self:IsThreeMode())
    KTool.SetActive(self.ImgThreeCost, self:IsThreeMode())

    -- refresh consume
    -- local triple = self:IsThreeMode() and 3 or 1
    local questVo = self:GetQuestDataByIndex()
    CfUtils.FillCommonBtnConsumePopNode(self.CommonBtnConsumePop, questVo.costItem, questVo.costNum)
end
function UIDisasterResponsePanel:IsThreeMode()
    return checkBool(self._isThree)
end

function UIDisasterResponsePanel:GetProgressByType(type)
    local questId = checkInt(equipQuestComp:GetQuestProgressById(type or self:GetSelectedType()))
    local questVo = checkTable(self:GetQuestDataByQuestId(questId))
    return checkInt(questVo.regionLevel)
end
------------------------------------------------------ public
function UIDisasterResponsePanel:InitData()
    ---@type BaseSetting
    self._questSetting = CfUtils.GetWholeVo(AutoIds.IdSetting848, "QuestSeniorEquipVo")
    ---@type BaseSetting
    self._questTypeSetting = CfUtils.GetCf(AutoIds.IdSetting847, "QuestSeniorEquipTypeVo")

    ---@param voData QuestSeniorEquipChapterVo
    for _, voData in pairs(self._questSetting) do
        if not self._allRankMap[tonumber(voData.type)] then
            self._allRankMap[tonumber(voData.type)] = {}
        end
        self._allRankMap[tonumber(voData.type)][tonumber(voData.regionLevel)] = tonumber(voData.id)
    end
end

function UIDisasterResponsePanel:InitView()
    -- init list view
    local chapterNum = self._questTypeSetting:Count()
    if not self.ChapterListView.IsListViewInit then
        self.ChapterListView:InitListView(chapterNum, Bind(self, self.OnGetChapterItemByIndex))
    else
        GameUtils.ReloadData(self.ChapterListView, chapterNum)
    end

    -- init tab
    self._isThree = equipQuestComp:IsThreeTripleMode()
    local questId = equipQuestComp:GetLastSubEquipPassedQuestId()
    local questVo = self:GetQuestDataByQuestId(questId)

    self:SetSelectedType(0)
    if questVo ~= nil and next(questVo) ~= nil then
        self:SetSelectedType(questVo.type, questVo.regionLevel, true)
    else
        self:SetSelectedType(1, nil, true)
    end
end

function UIDisasterResponsePanel:PlayChapterCellAnim(index, status)
    local node = self.ChapterListView:GetShownItemByItemIndex(index - 1)
    if node then
        ---@type UIDisasterResponseChapterNode
        local env = CfUtils.GetLuaScr(node, "Game.UI.FightReady.UIFastRelief.UIDisasterResponse.UIDisasterResponseChapterNode")
        if env then
            env:RefreshSelectedStatus(status)
        end
    end
end

--------------------------------------------------------------------------------handler

function UIDisasterResponsePanel:OnGetChapterItemByIndex(listView, index)
    if index < 0 then
        return nil
    end
    local cell = listView:NewListViewItem("Cell")
    ---@type UIDisasterResponseChapterNode
    local env = CfUtils.GetLuaScr(cell, "Game.UI.FightReady.UIFastRelief.UIDisasterResponse.UIDisasterResponseChapterNode")
    if env then
        env:RefreshSelf(self:GetChapterDataByIndex(index + 1), self:GetSelectedType() == index + 1)
        env:SetClickCB(function(type)
            self:SetSelectedType(type)
        end)
    end
    return cell
end

function UIDisasterResponsePanel:OnGetRankItemByIndex(listView, index)
    if index < 0 then
        return
    end

    local cell = listView:NewListViewItem("Cell")
    ---@type UIDisasterResponseRankNode
    local env = CfUtils.GetLuaScr(cell, "Game.UI.FightReady.UIFastRelief.UIDisasterResponse.UIDisasterResponseRankNode")
    if env then
        local questData = self:GetQuestDataByIndex(index + 1)
        env:RefreshSelf(questData, self:GetProgressByType(questData.type), self:GetSelectedRank() == questData.regionLevel)
        env:SetClickCB(function(rank, isUnlocked)
            self:SetSelectedRank(rank, false, isUnlocked)
        end)
    end
    return cell
end

function UIDisasterResponsePanel:OnClickGoToMapBtnHandler()
    local questVo = self:GetQuestDataByIndex()
    local questId = self:GetQuestIdByIndex()
    local progress = self:GetProgressByType(questVo.type)
    local rankLevel = checkNumber(questVo.regionLevel)
    if progress >= (rankLevel - 1) then
        ---解锁状态
        if GoodsUtils.GetThingNo(questVo.costItem) >= checkNumber(questVo.costNum) then
            --print("questId------->>"..questId)
            --equipQuestComp:SetCurSeniorLastQuestId(self:GetQuestIdByIndex())
            equipQuestComp:SetLastSubEquipPassedQuestId(self:GetQuestIdByIndex())

            equipQuestComp:SetTripleMode(self:IsThreeMode() and 1 or 0)
            UIModule.OpenDialog({ id = Constants.UITypeIds.UIFightTeamChoose, parameters = { levelId = questId, isThreeTripleMode = equipQuestComp:IsThreeTripleMode() } }, {
                { id = Constants.UITypeIds.UIFastReliefDisasterResponseDialog }
            })
        else
            GameUtils.Toast(localize("道具不足"))
        end
    end
end

function UIDisasterResponsePanel:OnClickThreeBtnHandler()
    if not equipQuestComp:IsPassQuestById(self:GetQuestIdByIndex()) then
        GameUtils.Toast(localize("请先通关此关卡"))
    else
        --equipQuestComp:SetTripleMode((not self:IsThreeMode()) and 1 or 0)
        self:SetThreeModeStatus(not self:IsThreeMode())
    end
end

return UIDisasterResponsePanel